SELECT Станции_для_сводной_2004.*, Станции_по_углям_2_2004.topl, Станции_по_углям_2_2004.pertop, [nust]*[pertop]/100 AS dnust, [e]*[pertop]/100 AS DE, Станции_по_углям_2_2004.rtop
FROM Станции_по_углям_2_2004 INNER JOIN Станции_для_сводной_2004 ON (Станции_по_углям_2_2004.NUMB1120=Станции_для_сводной_2004.NUMB1120) AND (Станции_по_углям_2_2004.YEAR=Станции_для_сводной_2004.YEAR);
